    def get_bar(self, asset, dt, frequency, fields=None):
        """
        根据 dt 来获取对应的 Bar 数据

        :param asset: 指定合约对象
        :type asset: : dict

        :param dt: 指定日期
        :type dt: : calendar_datetime

        :param frequency: 周期频率，`1d` 表示日周期, `1m` 表示分钟周期
        :type frequency: : str

        :param fields: 字段
        :type fields: list / str

        :return value: 指定的Bar 数据
        :type: : `numpy.ndarray` | None
        """
        param = get_date_of_range_to_kwargs(asset, dt, frequency)
        bars_array = self._all_bars_of_range(**(param))
        if len(bars_array) == 0:
            return EMPTY_BAR_NP_ARRAY
        elif frequency == Frequency.DAILY.value:
            dt = convert_date_to_date_int(dt)
        elif frequency[-1] == Frequency.MINUTE.value[-1]:
            dt = convert_dt_to_int(dt) // 100
        index = bars_array[BarDataEnum.DATETIME.value]
        pos = index.searchsorted(dt)
        if pos < 0 or pos >= len(bars_array) or bars_array['datetime'][pos] != dt:
            return EMPTY_BAR_NP_ARRAY
        elif fields:
            return bars_array[fields][pos]
        else:
            return bars_array[pos]
