    def get_kline_by_count(self, symbol, count, query_date, frequency, fields=None, fq=None, skip_suspended=False, include=False, execution_date=None):
        """
        获取历史数据，可指定取的条数

        :param symbol: 合约对象
        :type symbol: : str

        :param count: 数量, 返回的结果集的行数
        :type count: : int

        :param query_date: 数量, 查询日期
        :type query_date: : int | None

        :param frequency: 单位时间长度，默认1d ，支持1分钟线（1m）、5分钟线(5m)、15分钟线(15m)、
                          30分钟线(30m)、60分钟线(60m)、日线(1d)、周线(w)和月线(mo)频率数据
        :type frequency: : str

        :param fq: 赋权类型
        :type fq: str

        :param fields: 指明数据结果集中所支持输出字段
        :type fields: : list

        :param include: 包含本条数据
        :type include: bool
        filed值域范围：
        open              开盘价
        high              最高价
        low               最低价
        close             收盘价
        volume            交易量
        money             交易金额
        price             最新价
        high_limit        涨停价
        low_limit         跌停价
        is_open           停盘标识
        open_interest     持仓量（期货专用）
        basis_spread      期现差（股指期货专用）
        settlement        结算价（期货日线专用）
        prev_settlement   结算价（期货日线专用）

        :param skip_suspended: 是否跳过不交易日期(包括停牌, 未上市或者退市后的日期)，默认False不跳过，True 跳过，False 不跳过
        :type skip_suspended: : bool

        :return: pandas.DataFrame | 空pandas.DataFrame
        """
        asset = self.engine.basic_data_handler.get_security_info(symbol)[symbol]
        if len(asset) < 1 or count == 0 or fields is None:
            return EMPTY_DAY_BAR_NP_ARRAY
        else:
            pre_date = self.engine.basic_data_handler.get_pre_date(count, cur_date, frequency, asset['trading_time'])
            pre_date = self.engine.basic_data_handler.get_pre_date(count, cur_date, frequency)
            if count > 0:
                params = set_params_to_kwargs(asset, pre_date, cur_date, frequency)
            else:
                params = set_params_to_kwargs(asset, cur_date, pre_date, frequency)
            bars_ndarr = self._all_bars_of_cache(**(params))
            if len(bars_ndarr) == 0:
                return EMPTY_DAY_BAR_NP_ARRAY if fields is None else EMPTY_DAY_BAR_NP_ARRAY[fields]
            else:
                tmp_start_date = convert_int14_to_int(convert_dt_to_int(pre_date), frequency)
                bars_ndarr_datetime = bars_ndarr[BarDataEnum.DATETIME.value]
                if count > 0:
                    if include:
                        if bars_ndarr_datetime.searchsorted(query_date) == len(bars_ndarr_datetime):
                            start_pos = bars_ndarr_datetime.searchsorted(tmp_start_date)
                        else:
                            start_pos = bars_ndarr_datetime.searchsorted(tmp_start_date, side='right')
                    else:
                        start_pos = bars_ndarr_datetime.searchsorted(tmp_start_date)
                    bars_ndarr = bars_ndarr[start_pos:]
                else:
                    if include:
                        if bars_ndarr_datetime.searchsorted(query_date) == len(bars_ndarr_datetime):
                            end_pos = bars_ndarr_datetime.searchsorted(tmp_start_date, side='right')
                        else:
                            end_pos = bars_ndarr_datetime.searchsorted(tmp_start_date)
                    else:
                        end_pos = bars_ndarr_datetime.searchsorted(tmp_start_date, side='right')
                    bars_ndarr = bars_ndarr[:end_pos]
                if len(bars_ndarr) == 0:
                    return EMPTY_DAY_BAR_NP_ARRAY if fields is None else EMPTY_DAY_BAR_NP_ARRAY[fields]
                else:
                    bars_ndarr_datetime = bars_ndarr[BarDataEnum.DATETIME.value]
                    query_date = convert_int14_to_int(query_date, frequency)
                    if count > 0:
                        if include:
                            pos = bars_ndarr_datetime.searchsorted(query_date, side='right')
                        else:
                            pos = bars_ndarr_datetime.searchsorted(query_date)
                        if pos >= count:
                            left = pos - count
                        else:
                            left = 0
                        bars_ndarr = bars_ndarr[left:pos]
                    else:
                        if include:
                            pos = bars_ndarr_datetime.searchsorted(query_date)
                        else:
                            pos = bars_ndarr_datetime.searchsorted(query_date, side='right')
                        right = pos - count
                        bars_ndarr = bars_ndarr[pos:right]
                    if len(bars_ndarr) == 0:
                        return EMPTY_DAY_BAR_NP_ARRAY if fields is None else EMPTY_DAY_BAR_NP_ARRAY[fields]
                    elif fq is not None:
                        if asset['type'] == AssetType.FUTURE.value:
                            return bars_ndarr if fields is None else bars_ndarr[fields]
                        else:
                            tmp_fields = ['price', 'last']
                            tmp_fields.extend(CAL_EXRIGHTS_COLUMNS)
                            if isinstance(fields, str) and fields not in tmp_fields:
                                return bars_ndarr if fields is None else bars_ndarr[fields]
                            if isinstance(fields, list) and len(set(fields).intersection(set(tmp_fields))) == 0:
                                return bars_ndarr if fields is None else bars_ndarr[fields]
                            elif fq == DIVIDEND_CALC_TYPE[0] or fq == DIVIDEND_CALC_TYPE[1] or fq == DIVIDEND_CALC_TYPE[2]:
                                dividends = self.engine.basic_data_handler.get_dividend(symbol, None)
                                if len(dividends) == 0:
                                    return bars_ndarr if fields is None else bars_ndarr[fields]
                                elif isinstance(dividends, pd.DataFrame):
                                    dividend_dict = {}
                                    for i in range(len(dividends)):
                                        line = dividends.iloc[i]
                                        dividend_dict[int(line['date'])] = [line[c] for c in DIVIDEND_COLUMNS]
                                    other_names = list(set(other_names) - set(new_exrights_fields))
                                    bars_tmp = bars_ndarr[names]
                                    index = bars_ndarr[BarDataEnum.DATETIME.value]
                                    base_bars = np.empty(shape=(len(index), len(bars_tmp.dtype)), dtype=np.float64)
                                    for i in range(len(index)):
                                        for j, name in enumerate(bars_tmp.dtype.names):
                                            base_bars[i][j] = bars_tmp[name][i]
                                    save_digits = 2
                                    if symbol[0] in ('1', '5'):
                                        save_digits = 3
                                    if fq == 'dypre':
                                        dividend_date_list = list(dividend_dict.keys())
                                        dividend_date_list.sort()
                                        if frequency.find('m') == 1:
                                            query_date = int(query_date / 10000)
                                        if frequency == '1d' and execution_date is not None:
                                            query_date = execution_date
                                        if len(dividend_date_list) >= 1 and query_date >= dividend_date_list[-1]:
                                            adjust_bars_tuple = CalExrights(base_bars, index, dividend_dict, 'pre', save_digits)
                                        else:
                                            index_list = list(index)
                                            index_list.append(query_date)
                                            index_new = np.array(index_list)
                                            adjust_bars_tuple = CalExrights(base_bars, index_new, dividend_dict, fq, save_digits)
                                    else:
                                        adjust_bars_tuple = CalExrights(base_bars, index, dividend_dict, fq, save_digits)
                                    ajust_bars = adjust_bars_tuple[0]
                                    ajust_bars = np.array([tuple(_d) for _d in ajust_bars], dtype=bars_tmp.dtype)
                                    bars_ndarr_data = np.empty(dtype=bars_ndarr.dtype, shape=len(index))
                                    for i in range(len(index)):
                                        bars_ndarr_data[BarDataEnum.DATETIME.value][i] = index[i]
                                        for name in names:
                                            bars_ndarr_data[name][i] = ajust_bars[name][i]
                                        for name in other_names:
                                            bars_ndarr_data[name][i] = bars_ndarr[name][i]
                                        if len(close_names) > 0:
                                            for name in close_names:
                                                bars_ndarr_data[name][i] = ajust_bars['close'][i]
                                        continue
                                    if frequency == '1d' and bars_ndarr['unlimited'][0] > 0:
                                        length = len(bars_ndarr_data)
                                        for i in range(length):
                                            if bars_ndarr_data['unlimited'][i] > 0:
                                                bars_ndarr_data['high_limit'][i] = bars_ndarr['high_limit'][i].copy()
                                                bars_ndarr_data['low_limit'][i] = bars_ndarr['low_limit'][i].copy()
                                    return bars_ndarr_data if fields is None else bars_ndarr_data[fields]
                                elif isinstance(dividends, dict):
                                    dividends_tmp = dividends[symbol]
                                    dividend_dict = {key: [item[c] for c in DIVIDEND_COLUMNS] for key, item in dividends_tmp.items()}
                                else:
                                    raise TypeError(_('Unsupported dividends data type, expect dict /  pd.DataFrame, got{}'.format(dividends.__class__)))
                                new_exrights_fields = list(bars_ndarr.dtype.names[8:11])
                                names = list(bars_ndarr.dtype.names[1:7]) + new_exrights_fields
                                other_names = list(bars_ndarr.dtype.names[7:])
                                close_names = list()
                                if 'price' in other_names:
                                    other_names.remove('price')
                                    close_names.append('price')
                                if 'last' in other_names:
                                    other_names.remove('last')
                                    close_names.append('last')
    def get_kline_by_date(self, symbol, start_date, end_date, frequency, fields=None, fq=None, skip_suspended=False, include=False):
        return None
    def get_settle_price(self, symbol, dt):
        """
        获取期货结算价格
        :param symbol:合约名称
        :type symbol: : str
        
        :param dt:指定日期
        :type dt: : datetime.date
        
        :return value:返回数据
        :type:float | np.nan
        """
        asset = self.engine.basic_data_handler.get_security_info(symbol)[symbol]
        if len(asset) < 1:
            return np.nan
        else:
            data = self.get_bar(asset, dt, Frequency.DAILY.value, BarDataEnum.CLOSE.value)
            if data:
                if isinstance(data, np.float64):
                    re_data = round(data, 2)
                else:
                    re_data = np.nan
            else:
                re_data = np.nan
            return re_data
    def get_prev_settlement(self, symbol, dt):
        """
        获取期货昨日结算价格
        :param symbol:合约名称
        :type symbol: : str
        
        :param dt:指定日期
        :type dt: : datetime.date
        
        :return value:返回数据
        :type: float | np.nan
        """
        pre_dt = self.engine.basic_data_handler.get_pre_date(1, dt, Frequency.DAILY.value)
        return self.get_settle_price(symbol, pre_dt)
